import { Inject, Injectable } from '@nestjs/common';
import type { Knex } from 'knex';
import { KNEX } from '../database/database.module.js';
import { isUniqueViolation } from '../database/unique-violation.js';

const USERS = 'users';
const EMAIL_UNIQUE = 'users_email_unique';

export interface NewUser {
  /** UUID generated by the app. */
  id: string;
  /** Already trimmed and lower-cased. */
  email: string;
  passwordHash: string;
  phone: string | null;
  createdAt: Date;
}

export const InsertUserResult = {
  Created: 'created',
  EmailTaken: 'emailTaken',
} as const;

export type InsertUserResult = (typeof InsertUserResult)[keyof typeof InsertUserResult];

@Injectable()
export class UsersRepository {
  constructor(@Inject(KNEX) private readonly db: Knex) {}

  async insert(user: NewUser): Promise<InsertUserResult> {
    try {
      await this.db(USERS).insert({
        id: user.id,
        email: user.email,
        password_hash: user.passwordHash,
        phone: user.phone,
        created_at: user.createdAt,
        updated_at: user.createdAt,
      });
      return InsertUserResult.Created;
    } catch (error) {
      if (isUniqueViolation(error, EMAIL_UNIQUE)) return InsertUserResult.EmailTaken;
      throw error;
    }
  }
}
